<?php

namespace Modules\ChildRecord\Database\Factories;

use Illuminate\Database\Eloquent\Factories\Factory;
use Modules\ChildRecord\Models\Child;
use Modules\ChildRecord\Models\Visit;
use Modules\Clinic\Database\Factories\HealthCenterFactory;
use Modules\Clinic\Models\HealthCenter;
use Modules\Clinic\Models\PractitionerProfile;
use Modules\Tenant\Models\Tenant;
use QCH\Core\Support\TenantTime;

/**
 * @extends Factory<Visit>
 *
 * NOTE: receipt_number is always server-generated by VisitService; direct
 * ::create() (bypassing the service, as factories do) must still satisfy the
 * NOT NULL column, so a random placeholder is provided here for pure model
 * tests. HTTP-level tests exercise the real VisitService sequence instead.
 */
class VisitFactory extends Factory
{
    protected $model = Visit::class;

    public function definition(): array
    {
        return [
            'child_id' => fn () => Child::factory()->create()->id,
            'health_center_id' => fn () => HealthCenter::factory()->create([
                'municipality_id' => HealthCenterFactory::defaultMunicipality()->id,
            ])->id,
            'receipt_number' => 'V-'.date('Y').'-'.str_pad((string) $this->faker->unique()->numberBetween(1, 999999), 6, '0', STR_PAD_LEFT),
            'physical_receipt_number' => null,
            'visit_date' => TenantTime::today(Tenant::DEFAULT_TIMEZONE),
            'practitioner_id' => fn () => PractitionerProfile::factory()->create()->id,
        ];
    }
}
